def solve(n):
    """Return the number of prime numbers strictly less than n.
    Handles non‑positive and non‑integer inputs gracefully by treating them as 0.
    Uses the Sieve of Eratosthenes with O(n) memory; for very large n the
    implementation falls back to a simple trial‑division count to avoid memory errors.
    """
    # Ensure n is an integer >= 0
    try:
        n = int(n)
    except Exception:
        return 0
    if n <= 2:
        return 0
    # If n is moderately sized, use sieve; else use trial division to save memory.
    # Threshold chosen to be safe for the execution environment.
    if n <= 5_000_000:
        size = n
        is_prime = bytearray(b'\x01') * size
        # 0 and 1 are not prime
        if size > 0:
            is_prime[0] = 0
        if size > 1:
            is_prime[1] = 0
        import math
        limit = int(math.isqrt(n - 1))
        for p in range(2, limit + 1):
            if is_prime[p]:
                start = p * p
                step = p
                # calculate how many entries to zero out
                count = (n - 1 - start) // step + 1
                is_prime[start:n:step] = b'\x00' * count
        return sum(is_prime)
    else:
        # Fallback: trial division counting primes < n
        def is_prime_num(x):
            if x < 2:
                return False
            if x % 2 == 0:
                return x == 2
            i = 3
            import math
            limit = int(math.isqrt(x))
            while i <= limit:
                if x % i == 0:
                    return False
                i += 2
            return True
        cnt = 0
        for num in range(2, n):
            if is_prime_num(num):
                cnt += 1
        return cnt

