def solve(grid):
    """Count the number of islands (connected groups of 1s) in a 2D grid.
    Connection is 4-directional (up, down, left, right). Handles empty grid.
    """
    if not grid:
        return 0
    n = len(grid)
    m = len(grid[0]) if n > 0 else 0
    visited = [[False] * m for _ in range(n)]
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if x < 0 or x >= n or y < 0 or y >= m:
                continue
            if visited[x][y] or grid[x][y] != 1:
                continue
            visited[x][y] = True
            stack.extend([(x-1, y), (x+1, y), (x, y-1), (x, y+1)])
    count = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1 and not visited[i][j]:
                dfs(i, j)
                count += 1
    return count

