def solve(s):
    """Validate IPv4 address.
    Rules:
    - Exactly four parts separated by '.'
    - Each part is a decimal number 0-255
    - No leading zeros unless the part is exactly '0'
    """
    parts = s.split('.')
    if len(parts) != 4:
