def solve(n, edges, source, target):
    # n nodes 0..n-1, edges list of [u,v,w]
    import heapq
    graph = [[] for _ in range(n)]
    for u,v,w in edges:
        graph[u].append((v,w))
        graph[v].append((u,w))
    INF = 10**18
    dist = [INF]*n
    dist[source]=0
    pq=[(0,source)]
    while pq:
        d,u=heapq.heappop(pq)
        if d!=dist[u]:
            continue
        if u==target:
            break
        for v,w in graph[u]:
            nd=d+w
            if nd<dist[v]:
                dist[v]=nd
                heapq.heappush(pq,(nd,v))
    return dist[target] if dist[target]!=INF else -1

