import heapq

def solve(n, edges):
    adj = [[] for _ in range(n)]
    for a, b, w in edges:
        adj[a].append((b, w))
        adj[b].append((a, w))
    dist = [float('inf')] * n
    dist[0] = 0
    pq = [(0, 0)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        if u == n - 1:
            return d
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return dist[n - 1] if dist[n - 1] != float('inf') else -1

def solve(n, b):
    """Convert integer n to a string representation in base b (2 <= b <= 36).
    Uses digits 0-9 then a-z for values 10-35. Handles negative numbers.
    """
    if b < 2 or b > 36:
        raise ValueError("Base b must be between 2 and 36")
    if n == 0:
        return '0'
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    neg = n < 0
    n = -n if neg else n
    res = []
    while n > 0:
        n, rem = divmod(n, b)
        res.append(digits[rem])
    if neg:
        res.append('-')
    return ''.join(reversed(res))

